    handle1.join().unwrap();
    handle2.join().unwrap();

    // Verify that the counter equals two
    let final_value = c.load(Ordering::SeqCst);
    assert_eq!(final_value, 2, "Counter should be 2 after both increments");

    // Print exactly the line `DONE done=1` and then exit
    println!("DONE done=1");
