        while !*flag {
            flag = cvar.wait(flag).unwrap();
        }
        // Lock is released when `flag` goes out of scope
    });

    notifier_handle.join().unwrap();
    waiter_handle.join().unwrap();

    println!("DONE ready=true");
}
